# Examine holes (0-components) and changed 1-cells; test "hole + changed cells form rectangles" theory
def comps_of(M, val):
    h,w = M.shape; lab=-np.ones((h,w),int); res=[]
    for r in range(h):
        for c in range(w):
            if M[r,c]==val and lab[r,c]<0:
                cid=len(res); q=deque([(r,c)]); lab[r,c]=cid; cells=[(r,c)]; touch=False
                while q:
                    y,x=q.popleft()
                    if y in(0,h-1) or x in(0,w-1): touch=True
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<h and 0<=nx<w and M[ny,nx]==val and lab[ny,nx]<0:
                            lab[ny,nx]=cid; q.append((ny,nx)); cells.append((ny,nx))
                res.append((cells,touch))
    return res

