def interior_fill(I, mark_anom=True):
    I = I.copy(); h,w = I.shape
    anoms = set(map(tuple, np.argwhere((I!=0)&(I!=1))))
    out = I.copy()
    for r in range(1,h-1):
        for c in range(1,w-1):
            if I[r,c]==1:
                nb = [I[r+dr,c+dc] for dr in(-1,0,1) for dc in(-1,0,1) if (dr,dc)!=(0,0)]
                if all(v==1 or (r+dr,c+dc) in anoms for v,(dr,dc) in zip(nb,[ (dr,dc) for dr in(-1,0,1) for dc in(-1,0,1) if (dr,dc)!=(0,0)])):
                    out[r,c] = I[next(iter(anoms))[0], next(iter(anoms))[1]] if False else None
    return out
# simpler: assign anomaly color of nearest anomaly
from scipy import ndimage
def solve2(I):
    I=I.copy(); h,w=I.shape
    amask = (I!=0)&(I!=1)
    # nearest anomaly color per cell (distance transform)
    labs, n = ndimage.label(amask)
    centers = ndimage.center_of_mass(amask, labs, range(1,n+1))
    out=I.copy()
    for r in range(h):
        for c in range(w):
            if I[r,c]==1:
                ok=True
                for dr in(-1,0,1):
                    for dc in(-1,0,1):
                        rr,cc=r+dr,c+dc
                        if 0<=rr<h and 0<=cc<w:
                            if I[rr,cc]==0: ok=False
                        else: ok=False
                if ok:
                    d,y,x = min((abs(r-ay)+abs(c-ax), ay, ax) for ay,ax in zip(*np.where(amask)))
                    out[r,c]=I[y,x]
    return out
